CREATE TABLE IF NOT EXISTS "Usuarios" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" VARCHAR(255) NOT NULL,
  "email" VARCHAR(255) NOT NULL UNIQUE,
  "senha" VARCHAR(255) NOT NULL,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "Campeonatos" (
  "id_campeonato" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome_campeonato" VARCHAR(150) NOT NULL,
  "descricao" TEXT,
  "max_times" INTEGER NOT NULL DEFAULT 16,
  "data_inicio" TIMESTAMPTZ NOT NULL,
  "data_fim" TIMESTAMPTZ,
  "status" VARCHAR(20) NOT NULL DEFAULT 'ABERTO',
  "formato" VARCHAR(50) NOT NULL DEFAULT 'ELIMINATORIA',
  "id_organizador" INTEGER NOT NULL REFERENCES "Usuarios" ("id"),
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "campeonatos_id_organizador_idx"
  ON "Campeonatos" ("id_organizador");

CREATE TABLE IF NOT EXISTS "Times" (
  "id_time" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome_time" VARCHAR(100) NOT NULL,
  "tag_time" VARCHAR(10) NOT NULL UNIQUE,
  "logo" VARCHAR(255),
  "data_criacao" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "id_capitao" INTEGER NOT NULL REFERENCES "Usuarios" ("id"),
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "times_id_capitao_idx"
  ON "Times" ("id_capitao");

CREATE TABLE IF NOT EXISTS "jogadores" (
  "id_jogador" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome_jogador" VARCHAR(100) NOT NULL,
  "id_cadastrador" INTEGER NOT NULL REFERENCES "Usuarios" ("id"),
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "jogadores_id_cadastrador_idx"
  ON "jogadores" ("id_cadastrador");

CREATE TABLE IF NOT EXISTS "time_jogadores" (
  "id_time" INTEGER NOT NULL REFERENCES "Times" ("id_time")
    ON DELETE CASCADE ON UPDATE CASCADE,
  "id_jogador" INTEGER NOT NULL REFERENCES "jogadores" ("id_jogador")
    ON DELETE CASCADE ON UPDATE CASCADE,
  PRIMARY KEY ("id_time", "id_jogador")
);

CREATE INDEX IF NOT EXISTS "time_jogadores_id_jogador_idx"
  ON "time_jogadores" ("id_jogador");
